#!/usr/bin/env python3
import json
import re
from datetime import datetime, timedelta

def parse_alice(text):
    """Alice has UNAVAILABLE periods, we need to find available periods."""
    unavailable = []
    for line in text.splitlines():
        m = re.match(r"UNAVAILABLE: (\d{4}-\d{2}-\d{2}) to (\d{4}-\d{2}-\d{2})", line)
        if m:
            unavailable.append((datetime.strptime(m.group(1), "%Y-%m-%d"), datetime.strptime(m.group(2), "%Y-%m-%d")))

    # Sort by start date
    unavailable.sort()

    # Find available periods (gaps between unavailable periods)
    # We consider the year 2025
    available = []
    year_start = datetime(2025, 1, 1)
    year_end = datetime(2025, 12, 31)

    current = year_start
    for start, end in unavailable:
        if current < start:
            available.append({"start": current.strftime("%Y-%m-%d"), "end": (start - timedelta(days=1)).strftime("%Y-%m-%d")})
        current = max(current, end + timedelta(days=1))

    if current <= year_end:
        available.append({"start": current.strftime("%Y-%m-%d"), "end": year_end.strftime("%Y-%m-%d")})

    return available

def parse_bob(text):
    """Bob has SHIFT_CSV format with daily entries."""
    off_dates = []
    for line in text.splitlines():
        if line.startswith("SHIFT:"):
            parts = line.replace("SHIFT: ", "").split(",")
            if len(parts) == 3 and parts[1] == "off":
                off_dates.append(datetime.strptime(parts[0], "%Y-%m-%d"))

    if not off_dates:
        return []

    # Group consecutive dates into ranges
    off_dates.sort()
    ranges = []
    range_start = off_dates[0]
    range_end = off_dates[0]

    for d in off_dates[1:]:
        if d == range_end + timedelta(days=1):
            range_end = d
        else:
            ranges.append({"start": range_start.strftime("%Y-%m-%d"), "end": range_end.strftime("%Y-%m-%d")})
            range_start = d
            range_end = d
    ranges.append({"start": range_start.strftime("%Y-%m-%d"), "end": range_end.strftime("%Y-%m-%d")})

    return ranges

