    for m in re.finditer(r"(January|February|March|April|May|June|July|August|September|October|November|December)\s+(\d+)-(\d+),\s*(\d{4})", text):
        pass  # Already handled above

    # "August 4-31, 2025"
    # Already handled by the pattern above

    unavailable.sort()

    year_start = datetime(2025, 1, 1)
    year_end = datetime(2025, 12, 31)

    available = []
    current = year_start
    for start, end in unavailable:
        if current < start:
            available.append({"start": current.strftime("%Y-%m-%d"), "end": (start - timedelta(days=1)).strftime("%Y-%m-%d")})
        current = max(current, end + timedelta(days=1))

    if current <= year_end:
        available.append({"start": current.strftime("%Y-%m-%d"), "end": year_end.strftime("%Y-%m-%d")})

    return available

def parse_dana(text):
    """Dana has MIXED_JSON format with BUSY periods."""
    unavailable = []
    for line in text.splitlines():
        m = re.match(r"\s*BUSY: (\d{4}-\d{2}-\d{2}) to (\d{4}-\d{2}-\d{2})", line)
